\begin{corollary}
\label{topping-maxpr-finite-time-blowup}
\source{topping:page-0047}
\dcref{ch3:2.4}
\group{maximum-principle}

Let $g(t)$ be a Ricci flow on a closed manifold for $t\in[0,T)$. If
$R\geq\alpha>0$ at $t=0$, then $T\leq\frac{n}{2\alpha}$.
\end{corollary}

